import{a as e,i as t,u as n}from"./app-3hfLJP1Y.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/zh/posts/notes/ai-swe/01-llm.html","title":"01 LLM 模型层基础","lang":"zh-CH","frontmatter":{"lang":"zh-CH","title":"01 LLM 模型层基础","description":"Transformer 与 Attention、Tokenization、采样解码、上下文窗口、幻觉成因与模型选型等模型层高频主题","date":"2026-09-07T00:00:00.000Z","category":["后端开发"],"tag":["人工智能"],"head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"01 LLM 模型层基础\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2026-09-07T00:00:00.000Z\\",\\"dateModified\\":\\"2026-11-12T04:58:58.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"vexillium\\",\\"url\\":\\"https://vexillium2.github.io\\"}]}"],["meta",{"property":"og:url","content":"https://vexillium2.github.io/zh/posts/notes/ai-swe/01-llm.html"}],["meta",{"property":"og:site_name","content":"Vexilog"}],["meta",{"property":"og:title","content":"01 LLM 模型层基础"}],["meta",{"property":"og:description","content":"Transformer 与 Attention、Tokenization、采样解码、上下文窗口、幻觉成因与模型选型等模型层高频主题"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CH"}],["meta",{"property":"og:locale:alternate","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-11-12T04:58:58.000Z"}],["meta",{"property":"article:tag","content":"人工智能"}],["meta",{"property":"article:published_time","content":"2026-09-07T00:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-11-12T04:58:58.000Z"}],["link",{"rel":"alternate","hreflang":"zh-cn","href":"https://vexillium2.github.io/zh/posts/notes/ai-swe/01-llm.html"}]]},"git":{"createdTime":1788762188000,"updatedTime":1794459538000,"contributors":[{"name":"vexillium2","username":"vexillium2","email":"ntc_ip_rbm@163.com","commits":6,"url":"https://github.com/vexillium2"}]},"readingTime":{"minutes":49.44,"words":14831},"filePathRelative":"zh/posts/notes/ai-swe/01-llm.md","excerpt":"<p>这一章站在应用开发者的视角，把 LLM 的&quot;模型层&quot;讲清楚：不推冗长的数学推导，但要把 API 背后真正决定效果、成本、延迟的机制讲明白——注意力为什么这样设计、token 是怎么计价与管理的、采样参数各自在干什么、模型的能力是分几个阶段&quot;训&quot;出来的、o1/R1 这类推理模型改变了什么、长上下文为什么贵、幻觉从哪来以及如何在工程上压制、最后落到选型与上游 API 网关设计。面试里关于模型层的高频问题，也会分散到对应小节里直接回答，而不是单独堆一节&quot;面试题&quot;。</p>\\n<h2>一、Transformer 与 Attention：一切的地基</h2>"}`),a={name:`01-llm.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<p>这一章站在应用开发者的视角，把 LLM 的&quot;模型层&quot;讲清楚：不推冗长的数学推导，但要把 API 背后真正决定效果、成本、延迟的机制讲明白——注意力为什么这样设计、token 是怎么计价与管理的、采样参数各自在干什么、模型的能力是分几个阶段&quot;训&quot;出来的、o1/R1 这类推理模型改变了什么、长上下文为什么贵、幻觉从哪来以及如何在工程上压制、最后落到选型与上游 API 网关设计。面试里关于模型层的高频问题，也会分散到对应小节里直接回答，而不是单独堆一节&quot;面试题&quot;。</p><h2 id="一、transformer-与-attention-一切的地基" tabindex="-1"><a class="header-anchor" href="#一、transformer-与-attention-一切的地基"><span>一、Transformer 与 Attention：一切的地基</span></a></h2><p>在 Transformer 出现之前，序列建模的默认选择是 RNN（LSTM/GRU）。它们的问题本质上是结构性的：隐状态必须逐时间步串行更新，训练无法并行；长距离依赖只能靠隐状态一跳一跳地传递，反向传播经过很多时间步后梯度要么消失要么爆炸，模型实际能&quot;记住&quot;的范围很有限。2017 年的《Attention Is All You Need》给出了不同的建模方式：让任意两个位置之间都直接建立联系，距离恒为 1，同时序列内部完全可并行。这也是为什么 Transformer 从一出生就是&quot;并行友好 + 长依赖友好&quot;的，后续所有主流 LLM 都建立在这两个性质之上。</p><h3 id="decoder-only-是怎么长成主流的" tabindex="-1"><a class="header-anchor" href="#decoder-only-是怎么长成主流的"><span>Decoder-only 是怎么长成主流的</span></a></h3><p>现代 LLM（GPT、Claude、Llama、Qwen、DeepSeek 等）几乎清一色采用 <strong>Decoder-only</strong> 架构：输入经 Token Embedding + 位置编码进入 N 层 Transformer Block，每层是「因果掩码多头自注意力 + 前馈网络 FFN」，输出层对词表做 Softmax，得到下一个 token 的概率分布。原始论文里的 Encoder-Decoder 结构如今只在翻译、摘要这类任务上由 T5、BART 继承，不再是主流。</p><p>面试里几乎必问的一题就是：<strong>为什么大模型最终收敛到了 Decoder-only？</strong> 答案并不在&quot;Encoder 比 Decoder 弱&quot;这种笼统说法，而是几个可验证的工程事实叠加：</p><ul><li><strong>训练数据无限且无需标注</strong>。自回归的下一 token 预测任务天然可以把任意文本当作训练语料，规模可以一路涨上去；而 BERT 式的双向 MLM 也来自文本，但生成任务最终需要的是一个能&quot;说&quot;的模型。</li><li><strong>任务被统一成一个接口</strong>。翻译、摘要、问答、编程、Agent 工具调用，全都变成&quot;给一段输入，生成一段输出&quot;，任何新任务只需换 prompt 而不需要改模型结构，这也让后面的指令微调、RL 对齐、工具调用训练都发生在同一个生成框架内。</li><li><strong>推理/生成路径最短</strong>。Encoder-only 只能做理解不能生成；Encoder-Decoder 生成时需要先完整编码输入，decode 时还要跨 Encoder 的表示做交叉注意力，路径更长、更贵。Decoder-only 只有一个自回归解码流。</li><li><strong>工程上最顺</strong>。因果掩码 + KV Cache 使自回归生成可以逐 token 流式推进；而 KV Cache（后面有专节）在 Encoder-Decoder 里同样存在，但交叉注意力还会额外缓存 Encoder 输出。</li></ul><p>另有一种流传很广的说法：Decoder-only 的因果注意力矩阵是下三角、理论上是满秩的，因此表达能力比&quot;低秩&quot;的双向注意力更强。这个论点作为面试谈资可以提，但它不是主流共识，也不构成 Decoder-only 胜出的决定性原因——真正把它推到主流位置的是上面几条关于数据、任务统一与工程效率的硬事实。如果被追问，建议把回答落在这几条上而不是&quot;满秩&quot;上。</p><h3 id="注意力计算-q、k、v-与缩放点积" tabindex="-1"><a class="header-anchor" href="#注意力计算-q、k、v-与缩放点积"><span>注意力计算：Q、K、V 与缩放点积</span></a></h3><p>单头注意力的核心公式：</p><p><code>Attention(Q, K, V) = softmax(QKᵀ / √d_k) V</code></p><p>原始输入 X 经过三个独立的线性投影得到 Q（Query，查询）、K（Key，键）、V（Value，值）。流程是：Q 与所有 K 做点积得到注意力分数，Softmax 归一化成权重，再对 V 加权求和得到输出。围绕这个公式有三个点，是后端面试追问的重灾区：</p><p><strong>K 和 V 为什么要解耦成两套矩阵？</strong> 可以这样理解分工：K 负责&quot;匹配&quot;，决定哪些历史位置与本查询相关；V 负责&quot;内容&quot;，决定真正被取出来的信息。二者解耦，注意力才有能力表达&quot;检索到什么&quot;与&quot;提取什么&quot;是不同的两件事；如果用一个矩阵同时决定，表达能力会显著下降。自回归 decode 时只缓存 K、V 而不缓存 Q，也正是这个分工的体现——Q 只属于当前生成步，K/V 属于所有历史位置。</p><p><strong>为什么要除以 √d_k？</strong> 这是数值稳定性设计。Q、K 各维通常是零均值同方差，两向量点积的方差近似等于维度 d_k。d_k 越大，点积分数分布越分散，Softmax 会过早进入饱和区：最大的那个分数附近梯度趋近于 0，其余位置梯度几乎为 0，模型很难学。除以 √d_k 把方差拉回 1，让 Softmax 保持在一个梯度健康的区间。工程上类似的&quot;除根号维度&quot;的缩放手法在很多注意力变体里都会复现。</p><p><strong>因果掩码（Causal Mask）在做什么？</strong> Decoder 需要保证当前位置只能看到自己和左侧的 token，因此在 Softmax 之前把右侧位置的分数置为 −∞（实践中用一个大负数掩码），防止信息从&quot;未来&quot;泄漏进来，维持自回归的单向性。训练时所有位置并行计算但各自只能 attend 到前缀，推理时则退化为逐 token 生成。</p><h3 id="多头注意力、ffn-与位置编码" tabindex="-1"><a class="header-anchor" href="#多头注意力、ffn-与位置编码"><span>多头注意力、FFN 与位置编码</span></a></h3><p>多头注意力（MHA）把 Q/K/V 按头拆分，每个头在自己的子空间里独立做注意力，再拼接投影。多头的意义是让不同的头各司其职：有的头建模局部相邻关系，有的头建模长距离指代，有的头关注句法或重复模式。与其说&quot;多头提升了表达力&quot;，不如说它给模型提供了多个并行的关系子空间，并且每个头的 d_k 变小了，计算代价也更可控。</p><p>FFN 是每个 Block 的第二部分，两层线性变换夹一个激活函数（现在主流是 SwiGLU 这类门控变体）。它的参数量大约占整个模型的三分之二——注意力虽然名字响亮，但模型里真正的&quot;存储体&quot;是 FFN。面试题&quot;模型参数主要分布在哪&quot;的答案就在这里：<strong>注意力负责&quot;路由与关联&quot;，FFN 负责&quot;记忆与变换&quot;，后者的参数量远大于前者</strong>。</p><p>Transformer 本身对位置是无感的：同样的 token 序列打乱顺序，注意力结果不变。位置信息必须显式注入：</p><table><thead><tr><th>方法</th><th>代表模型</th><th>机制与特点</th></tr></thead><tbody><tr><td>Sinusoidal 固定编码</td><td>原版 Transformer</td><td>无需学习、可确定性外推到任意长度，但无相对位置信息</td></tr><tr><td>Learned PE</td><td>BERT、GPT-2</td><td>可学习，拟合训练长度内的位置效果好，超出后基本失效</td></tr><tr><td>RoPE</td><td>LLaMA、Qwen、Gemma</td><td>通过旋转把位置编进内积，使注意力天然只依赖相对位置，成为开源主流</td></tr><tr><td>ALiBi</td><td>BLOOM</td><td>给注意力分数加随距离线性衰减的偏置，几乎零成本获得相对位置与外推性</td></tr></tbody></table><p>关于 RoPE 有一个很容易被讲错的点：<strong>它&quot;理论上可外推&quot;不等于&quot;实际能无限外推&quot;</strong>。RoPE 的相对位置性质让它比 Learned PE 更能适应超过训练长度的序列，但训练时没有见过的位置区间，注意力分数分布仍然会偏离训练分布，硬拉到 2 倍以上长度精度会明显下滑。所以厂商宣传的长上下文，多数是&quot;位置插值（linear/NTK/YaRN）+ 在超长数据上继续训练&quot;共同练出来的，不是换个位置编码就白送的。这个认知对后面理解长上下文成本非常关键。</p><h2 id="二、tokenization-token-是计费、窗口与成本的基本单位" tabindex="-1"><a class="header-anchor" href="#二、tokenization-token-是计费、窗口与成本的基本单位"><span>二、Tokenization：token 是计费、窗口与成本的基本单位</span></a></h2><p>LLM 既不按&quot;字&quot;也不按&quot;词&quot;理解输入，而是先把文本切成 <strong>token</strong>，再映射成向量。token 是计费的最小单位、上下文窗口的计量单位，也是 KV Cache（后面专节）按长度增长的单位——所以对应用开发者来说，tokenizer 不只是模型内部细节，而是成本模型的第一环。</p><h3 id="bpe-与子词分词" tabindex="-1"><a class="header-anchor" href="#bpe-与子词分词"><span>BPE 与子词分词</span></a></h3><p>主流方案是字节级 BPE（Byte-Pair Encoding，字节对编码）：从一个&quot;所有独立字符&quot;的初始词表出发，反复统计并合并语料中出现频率最高的相邻字符对，直到词表达到预设大小。训练完成后得到一个固定词表 + 一套合并规则；编码时尽量按最长匹配切分，解码把 token 逆向还原为文本。</p><p>几个必须知道的工程事实：</p><ul><li>词表是<strong>固定且不可跨模型复用</strong>的。不同模型（甚至同一家的不同代际）tokenizer 不同，同一段文本在不同模型下的 token 数、切分方式都不同。做 token 统计、缓存、截断判断时，必须用目标模型对应的 tokenizer，不能拿一个模型的计数去估算另一个。</li><li>词表里不仅有普通 token，还有特殊 token：序列边界（BOS/EOS）、填充、以及各家的功能 token——OpenAI 的 function calling、各家为 Agent 预留的工具调用 token、o1/R1 类模型的&quot;思考开始/结束&quot; token 都占着词表名额。这也是为什么指令微调格式一旦带上了专用 token，就必须由同一家模型消费。</li><li>BPE 是从语料频率里长出来的，<strong>对训练语料里出现多的语言/形态更友好</strong>，这是中文 token 开销偏高的直接原因。</li></ul><h3 id="中英文的-token-差异与计费直觉" tabindex="-1"><a class="header-anchor" href="#中英文的-token-差异与计费直觉"><span>中英文的 token 差异与计费直觉</span></a></h3><p>用 OpenAI 系的 tokenizer 观察时，大致手感是：<strong>英文约 1.3~1.5 token/词（一个词含前后空格常被切成 1~3 个 token）；中文常见字大多 1 个 token，部分常用双字词会合并成 1 个 token，生僻字可能被拆成 2~3 个</strong>。合起来的效果是：表达同一段意思，中文文本的 token 数通常明显多于英文。</p><p>这个差异带来的直接后果是成本与窗口占用差异：如果你的业务是中文为主、知识库也是中文文档，同样逻辑的 prompt 和上下文会比英文产品更早顶到窗口、更贵。做中文产品的成本估算，建议按&quot;目标模型实际跑一批真实样本&quot;来标定，不要套英文社区的&quot;每 100 token ≈ 75 词&quot;这类经验值。</p><h3 id="token-计费与上下文窗口管理的实操要点" tabindex="-1"><a class="header-anchor" href="#token-计费与上下文窗口管理的实操要点"><span>token 计费与上下文窗口管理的实操要点</span></a></h3><p>调用 LLM API 时，账单上的输入 token 数是<strong>整个 prompt</strong>（系统提示 + 历史 + 检索片段 + 当前问题）的 token 数，不是&quot;这次新增内容&quot;；输出按生成的 token 数单独计费，通常输出单价高于输入。结合这个计价模型，几个工程要点：</p><ul><li><strong>输入 token 决定 prefill 开销</strong>。请求越长，首次返回（TTFT）越慢。所以&quot;把更多东西塞进 prompt&quot;从来不是免费的，它同时购买成本与延迟。</li><li><strong>用 tokenizer-aware 的方式截断</strong>。客户端判断超窗时，不能用字符串长度或者按字符硬切，应用目标模型的 tokenizer 做截断，并尽量在句子/段落边界截，避免把一段语义拦腰切断。</li><li><strong>max_tokens 是&quot;输出预算&quot;</strong>。它限制的是本次生成的输出 token 上限，与输入窗口是两回事。设得过小，长回答会被静默截断（API 一般只给 finish_reason=length），代码/JSON 场景要主动检查 finish_reason 并处理截断，而不是当成完整结果。</li><li><strong>稳定前缀优先</strong>。把系统提示、工具定义这类不变内容放在 prompt 最前面并保持顺序稳定，才能命中各家的 prompt caching（见&quot;上下文窗口与 KV Cache&quot;一节），这部分成本可以从&quot;输入全价&quot;变成&quot;缓存读价&quot;。</li><li><strong>多轮对话按会话记账</strong>。历史每次全量重发，token 消耗随轮数线性增长，这是多轮应用成本曲线陡峭的根源；滑动窗口、历史摘要、外置记忆都是对这个问题的缓解手段。</li></ul><p>这里最典型的反例是：团队拿&quot;一个简单问题&quot;的 token 数去估算生产成本，上线后才发现多轮会话 + 检索片段让平均每次请求的输入 token 比预估大了一个数量级。成本模型的第一个教训就是：永远按真实流量形态（历史长度、检索注入、输出长度分布）来建模，而不是按单轮最小样本。</p><h2 id="三、采样与解码参数-temperature、top-p、top-k-与惩罚项" tabindex="-1"><a class="header-anchor" href="#三、采样与解码参数-temperature、top-p、top-k-与惩罚项"><span>三、采样与解码参数：temperature、top_p、top_k 与惩罚项</span></a></h2><p>模型每生成一个 token，本质上是在词表上算出一个概率分布，再按某种策略从分布里取出一个 token。temperature、top_p、top_k、repetition_penalty 这些参数控制的都是&quot;取 token&quot;这一小步——它们不改变模型的知识，只改变输出的确定性与多样性。把这一点记牢，就能避开一半的调参误区。</p><h3 id="从-logits-到采样-完整链路" tabindex="-1"><a class="header-anchor" href="#从-logits-到采样-完整链路"><span>从 logits 到采样：完整链路</span></a></h3><p>模型最后一层先输出每个 token 的原始分数 logits，经过 temperature 缩放后做 Softmax 变成概率分布，然后采样器从分布中取 token。三个关键步骤分开看：</p><ul><li><strong>temperature（T）</strong>：把 logits 除以 T 再 Softmax。T 越小分布越尖锐（趋近于贪心取最大概率），T→0 时行为等价于 greedy/argmax；T 越大分布越平坦，低概率 token 也有机会被选中，输出更多样。</li><li><strong>候选集截断（top_k / top_p）</strong>：采样前先收窄候选 token 集合，把明显不合理的尾巴切掉。</li><li><strong>惩罚项</strong>：对已经出现过的 token 降权，用来压重复，属于&quot;输出后验修正&quot;。</li></ul><h3 id="top-k-与-top-p-硬截断-vs-自适应截断" tabindex="-1"><a class="header-anchor" href="#top-k-与-top-p-硬截断-vs-自适应截断"><span>top_k 与 top_p：硬截断 vs 自适应截断</span></a></h3><ul><li><strong>top_k</strong>：只保留概率最高的 k 个 token 参与采样，其余置零。问题是 k 是写死的：分布很尖锐时 k 个候选里一堆是噪声，分布很平坦时 k 又可能把合理选项剪掉，需要针对任务手工试。</li><li><strong>top_p（核采样）</strong>：按概率从高到低累加，直到累积概率首次超过 p，得到一个<strong>大小自适应</strong>的候选集合。分布尖锐时集合小（行为趋近贪心），分布平坦时集合自动变大。因为不需要预知分布形状，top_p 在实践中比 top_k 更常用，很多推理框架的默认配置就是 temp + top_p。</li></ul><p>两者并不是二选一：可以先用 top_k 做硬性收窄，再用 top_p 做自适应收窄。但对大多数业务场景，<strong>只调 temperature 和 top_p 之一就够了</strong>，同时调多个参数容易互相打架且难以解释效果来自谁。</p><h3 id="三种-惩罚重复-的参数其实不是一回事" tabindex="-1"><a class="header-anchor" href="#三种-惩罚重复-的参数其实不是一回事"><span>三种&quot;惩罚重复&quot;的参数其实不是一回事</span></a></h3><ul><li><strong>repetition_penalty</strong>（HuggingFace / 开源推理栈）：对<strong>已经生成过的 token</strong> 的 logits 做乘法缩放，值 &gt;1 表示惩罚。作用对象是&quot;本轮已生成的序列&quot;。</li><li><strong>frequency_penalty</strong>（OpenAI 系）：按 token 在序列中出现的<strong>次数</strong>做线性减分，出现越多扣得越多。</li><li><strong>presence_penalty</strong>（OpenAI 系）：只要 token <strong>出现过</strong>就整体减一次分，不管出现几次，目的只是抑制&quot;重复提起&quot;。</li></ul><p>这三个参数数值不能跨 API 直接搬：OpenAI 的 penalty 是加性的，开源栈的 repetition_penalty 是乘性的，同一个&quot;1.5&quot;含义完全不同。惩罚开过头还有一个反直觉的副作用：模型为了绕开被惩罚的 token 会机械地换同义词，反而产生奇怪的措辞；在代码、术语密集、枚举清单这类&quot;重复本身是合法的&quot;场景里，重惩罚会明显伤害质量。</p><h3 id="调参与面试要点" tabindex="-1"><a class="header-anchor" href="#调参与面试要点"><span>调参与面试要点</span></a></h3><p>面试里最常考的版本是：<strong>temperature、top_k、top_p 各有什么用，怎么配合？</strong> 答题主线就是上面这条链路——temperature 控制分布整体锐度，top_k 是硬截断、top_p 是自适应截断，二者都作用在采样前的候选集上；贪心解码（或 T→0）最确定但最容易单调重复，采样才有多样性；事实/代码/结构化输出用低温度，创意写作用高温度。再补两个加分点：temperature 在贪心模式下基本不生效，别指望靠它&quot;提升确定性以外的正确性&quot;；低温度也压不掉幻觉，因为幻觉不是采样随机性带来的，这在后面的幻觉一节会展开。</p><p>实践上建议按固定顺序调：先确定任务类型定 temperature 档位，出现明显的候选噪声再引入 top_p（从 0.9 起试），确认是重复问题才考虑惩罚项。所有参数必须在自己业务的评测样本上对比验证——凭感觉堆参数是调参的大忌。</p><h2 id="四、从预训练到-sft-模型能力是分阶段-炼-出来的" tabindex="-1"><a class="header-anchor" href="#四、从预训练到-sft-模型能力是分阶段-炼-出来的"><span>四、从预训练到 SFT：模型能力是分阶段&quot;炼&quot;出来的</span></a></h2><p>对应用开发者来说，理解模型是怎么训出来的，最大的价值在于知道<strong>哪些东西改不了、哪些东西能通过 API 行为观察出来</strong>。今天看到的所有商用模型，基本都经过了「预训练 → SFT → 强化学习（偏好与验证）」这条流水线，每一阶段注入的能力类型完全不同。</p><h3 id="预训练-决定知识的-底子-与上限" tabindex="-1"><a class="header-anchor" href="#预训练-决定知识的-底子-与上限"><span>预训练：决定知识的&quot;底子&quot;与上限</span></a></h3><p>预训练的目标就是<strong>下一 token 预测</strong>：在海量无标注文本上，学出词法、语法、常识、世界知识，以及在足够规模下涌现出的推理雏形。它决定了模型知识的天花板、语言的流畅度、以及&quot;推理潜力&quot;有多大。</p><p>对开发者最关键的一个推论是：<strong>预训练阶段的知识是静态的</strong>，存在明确的训练数据截止时间，而且知识在参数里的存储是&quot;概率式&quot;的——模型不是查数据库，而是按分布重建，这正是长尾事实不可靠、需要检索兜底的根源。所有&quot;实时知识&quot;需求都必须在应用层用检索、工具等方式解决，靠的是系统设计而不是模型本身。</p><h3 id="sft-从-会续写-到-会听话" tabindex="-1"><a class="header-anchor" href="#sft-从-会续写-到-会听话"><span>SFT：从&quot;会续写&quot;到&quot;会听话&quot;</span></a></h3><p>SFT（监督微调）用高质量的人工指令数据（instruction / input / output 三元组）把通用模型调教成会遵循指令、按格式作答的助手。这里有一个常见误区：<strong>SFT 主要注入的是&quot;行为与格式&quot;，而不是知识</strong>。模型会回答某个领域的问题，主要因为知识在预训练里已经存在，SFT 只是教会它在被问到的时候把知识以正确形式说出来。所以&quot;用少量领域问答 SFT 就想让模型学到大量新知识&quot;是低效的，领域知识量大时更应该考虑 RAG 或扩充预训练语料。</p><h2 id="五、强化学习-从-rlhf-到-agentic-rl" tabindex="-1"><a class="header-anchor" href="#五、强化学习-从-rlhf-到-agentic-rl"><span>五、强化学习：从 RLHF 到 Agentic RL</span></a></h2><p>SFT 把模型训到&quot;会听话&quot;，这一章讲它怎么学会&quot;哪种回答更好&quot;，以及当任务从一条回答变成几十步操作时，这套方法怎么变形。</p><p>先看三个反例。让模型把登月讲给六岁小孩听，预训练模型会顺着&quot;解释&quot;往下续：解释万有引力、解释相对论、解释大爆炸——每句都通顺，没有一句在回答。问它谁第一个登上火星，它会补出 1971 年、一句&quot;个人的一小步&quot;，把不存在的事说得像真的。让它杀掉一个卡住的 Python 进程，它可能因为&quot;kill&quot;这个词拒绝回答——安全，但没用。</p><p>这三件事分别对应有用、诚实、无害。它们不是知识问题，是行为问题：模型知道的并不少，缺的是&quot;在该回答的时候、以该有的方式回答&quot;。</p><h3 id="为什么-sft-不够-四个限制" tabindex="-1"><a class="header-anchor" href="#为什么-sft-不够-四个限制"><span>为什么 SFT 不够：四个限制</span></a></h3><p>SFT 的样本是（指令，输入，输出）三元组，损失只算在输出 token 上。它像一个学生只看老师的满分答卷：能学会怎么写，但不知道什么样的写法更好。</p><p>InstructGPT 的论文把这件事说得很直接，四个限制绕不过去：</p><ul><li><strong>只有正例</strong>。示范告诉模型&quot;应该这样写&quot;，没告诉它&quot;那样写为什么不行&quot;。模型没见过被否定的回答，就学不会在两种都通顺的写法之间取舍。</li><li><strong>上限是示范者</strong>。模仿学到的是老师的风格、错误与偏见；学生很难超过老师。人工写一条理想回答很贵，写几万条更贵。</li><li><strong>写作成本高</strong>。让专家写一条满分回答要几十分钟；让两个人比较两条回答谁更好，只要几秒。偏好数据的采集成本比示范低一个量级。</li><li><strong>目标错位</strong>。交叉熵优化的是 token 级似然，而我们要的是&quot;有用、诚实、无害&quot;。这两个目标相关，但不相等：一段更可能被写出来的文字，不一定是一段更好的回答。</li></ul><p>思路于是换掉：不再让模型模仿某条回答，而是直接优化&quot;人更喜欢哪个回答&quot;。人只需要比较，不需要写作。</p><p>但一旦目标变成&quot;最大化人类打分&quot;，就不能再对参数求导了：打分是人给的，或者是一个奖励模型算的，它是 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>θ</mi></mrow><annotation encoding="application/x-tex">\\theta</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span></span> 的一个黑箱函数；采样又是离散的，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi mathvariant="normal">∇</mi><mi>θ</mi></msub><mi>r</mi><mo stretchy="false">(</mo><mi>x</mi><mo separator="true">,</mo><mi>y</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">\\nabla_\\theta r(x,y)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord">∇</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mclose">)</span></span></span></span> 根本不存在。</p><p>语言模型本身是一个策略：状态是 prompt 加已生成的 token，动作是下一个 token，策略是 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>π</mi><mi>θ</mi></msub><mo stretchy="false">(</mo><mi>y</mi><mo>∣</mo><mi>x</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">\\pi_\\theta(y \\mid x)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span>，奖励 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi><mo stretchy="false">(</mo><mi>x</mi><mo separator="true">,</mo><mi>y</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">r(x,y)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mclose">)</span></span></span></span> 在整条回答结束时给出。于是可以用策略梯度：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>J</mi><mo stretchy="false">(</mo><mi>θ</mi><mo stretchy="false">)</mo><mo>=</mo><msub><mi mathvariant="double-struck">E</mi><mrow><mi>x</mi><mo>∼</mo><mi>ρ</mi><mo separator="true">,</mo><mtext>\xA0</mtext><mi>y</mi><mo>∼</mo><msub><mi>π</mi><mi>θ</mi></msub><mo stretchy="false">(</mo><mo>⋅</mo><mo>∣</mo><mi>x</mi><mo stretchy="false">)</mo></mrow></msub><mrow><mo fence="true">[</mo><mi>r</mi><mo stretchy="false">(</mo><mi>x</mi><mo separator="true">,</mo><mi>y</mi><mo stretchy="false">)</mo><mo fence="true">]</mo></mrow></mrow><annotation encoding="application/x-tex">J(\\theta) = \\mathbb{E}_{x \\sim \\rho,\\ y \\sim \\pi_\\theta(\\cdot \\mid x)}\\left[r(x,y)\\right] </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1052em;vertical-align:-0.3552em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">x</span><span class="mrel mtight">∼</span><span class="mord mathnormal mtight">ρ</span><span class="mpunct mtight">,</span><span class="mspace mtight"><span class="mtight">\xA0</span></span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span><span class="mrel mtight">∼</span><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3488em;margin-left:-0.0359em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1512em;"><span></span></span></span></span></span></span><span class="mopen mtight">(</span><span class="mord mtight">⋅</span><span class="mrel mtight">∣</span><span class="mord mathnormal mtight">x</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3552em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">[</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mclose">)</span><span class="mclose delimcenter" style="top:0em;">]</span></span></span></span></span></span></p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi mathvariant="normal">∇</mi><mi>θ</mi></msub><mi>J</mi><mo>=</mo><mi mathvariant="double-struck">E</mi><mrow><mo fence="true">[</mo><mrow><mo fence="true">(</mo><mi>r</mi><mo stretchy="false">(</mo><mi>x</mi><mo separator="true">,</mo><mi>y</mi><mo stretchy="false">)</mo><mo>−</mo><mi>b</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo><mo fence="true">)</mo></mrow><msub><mi mathvariant="normal">∇</mi><mi>θ</mi></msub><mi>log</mi><mo>⁡</mo><msub><mi>π</mi><mi>θ</mi></msub><mo stretchy="false">(</mo><mi>y</mi><mo>∣</mo><mi>x</mi><mo stretchy="false">)</mo><mo fence="true">]</mo></mrow></mrow><annotation encoding="application/x-tex">\\nabla_\\theta J = \\mathbb{E}\\left[\\left(r(x,y) - b(x)\\right)\\nabla_\\theta \\log \\pi_\\theta(y \\mid x)\\right] </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord">∇</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathbb">E</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">[</span><span class="minner"><span class="mopen delimcenter" style="top:0em;">(</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal">b</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mclose delimcenter" style="top:0em;">)</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord">∇</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mclose delimcenter" style="top:0em;">]</span></span></span></span></span></span></p><p>这个式子只要求奖励是一个数，不要求它对 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>θ</mi></mrow><annotation encoding="application/x-tex">\\theta</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span></span> 可导。<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi mathvariant="normal">∇</mi><mi>log</mi><mo>⁡</mo><mi>π</mi></mrow><annotation encoding="application/x-tex">\\nabla \\log \\pi</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord">∇</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span></span></span></span> 告诉模型&quot;这条回答是怎么被写出来的&quot;，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi><mo>−</mo><mi>b</mi></mrow><annotation encoding="application/x-tex">r - b</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span></span></span></span> 告诉它&quot;这条回答比基准好多少&quot;：高于基准就提高概率，低于基准就降低。</p><p><strong>例</strong></p><p>同一篇文章的两个摘要，人给了 8.0 和 1.2。第二个摘要文笔更好，但漏掉了地震这个主题。分数不是 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>θ</mi></mrow><annotation encoding="application/x-tex">\\theta</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span></span> 的函数，梯度传不回去；但把 8.0 的那条概率调高、1.2 的那条调低，就是 RL 在这里做的全部事情。</p><p><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>b</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">b(x)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">b</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span> 是基线。它的选择不影响期望，只影响方差：基线越贴近&quot;这条 prompt 的平均水平&quot;，梯度噪声越小。PPO 用 critic 学这个基线，ReMax 用贪心答案的奖励，GRPO 用一组样本的平均——后面几种算法的主要差别，就在这个 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>b</mi></mrow><annotation encoding="application/x-tex">b</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span></span></span></span> 上。</p><h3 id="rlhf-三步与四个模型" tabindex="-1"><a class="header-anchor" href="#rlhf-三步与四个模型"><span>RLHF：三步与四个模型</span></a></h3><p>RLHF 把&quot;人&quot;拆成两个阶段：先用人写的示范教格式，再用人做的比较学偏好，最后用奖励模型替代人。</p><p><strong>第一步：SFT。</strong> 标注员写示范答案，做标准的交叉熵微调，得到一个初始策略 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>π</mi><mtext>ref</mtext></msub></mrow><annotation encoding="application/x-tex">\\pi_{\\text{ref}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ref</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。它已经会按指令回答，只是不知道哪种回答更好。</p><p><strong>第二步：奖励模型。</strong> 对同一个 prompt 采样多条回答，让人排序。绝对打分不可靠——同一条摘要，三个人可能给 8 分、5 分、9 分，每个人的尺子不同，同一个人过几天还会漂移；但&quot;这两条哪个更好&quot;稳定得多。于是用 Bradley–Terry 把比较变成概率：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>P</mi><mo stretchy="false">(</mo><msub><mi>y</mi><mi>w</mi></msub><mo>≻</mo><msub><mi>y</mi><mi>l</mi></msub><mo>∣</mo><mi>x</mi><mo stretchy="false">)</mo><mo>=</mo><mi>σ</mi><mrow><mo fence="true">(</mo><msub><mi>r</mi><mi>ϕ</mi></msub><mo stretchy="false">(</mo><mi>x</mi><mo separator="true">,</mo><msub><mi>y</mi><mi>w</mi></msub><mo stretchy="false">)</mo><mo>−</mo><msub><mi>r</mi><mi>ϕ</mi></msub><mo stretchy="false">(</mo><mi>x</mi><mo separator="true">,</mo><msub><mi>y</mi><mi>l</mi></msub><mo stretchy="false">)</mo><mo fence="true">)</mo></mrow></mrow><annotation encoding="application/x-tex">P(y_w \\succ y_l \\mid x) = \\sigma\\left(r_\\phi(x,y_w) - r_\\phi(x,y_l)\\right) </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≻</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">ϕ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">ϕ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mclose delimcenter" style="top:0em;">)</span></span></span></span></span></span></p><p>训练奖励模型就是最大化这个似然的负对数。奖励模型通常从 SFT 模型初始化，把最后的输出层换成一个标量头。</p><p><strong>第三步：PPO。</strong> 策略生成回答，奖励模型打分，PPO 把高分回答的概率推高，同时用一个 KL 项把策略拴在 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>π</mi><mtext>ref</mtext></msub></mrow><annotation encoding="application/x-tex">\\pi_{\\text{ref}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ref</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 附近：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><munder><mrow><mi>max</mi><mo>⁡</mo></mrow><mi>θ</mi></munder><mtext>\xA0</mtext><msub><mi mathvariant="double-struck">E</mi><mrow><mi>x</mi><mo separator="true">,</mo><mtext>\xA0</mtext><mi>y</mi><mo>∼</mo><msub><mi>π</mi><mi>θ</mi></msub></mrow></msub><mrow><mo fence="true">[</mo><msub><mi>r</mi><mi>ϕ</mi></msub><mo stretchy="false">(</mo><mi>x</mi><mo separator="true">,</mo><mi>y</mi><mo stretchy="false">)</mo><mo fence="true">]</mo></mrow><mo>−</mo><mi>β</mi><mo>⋅</mo><mrow><mi mathvariant="normal">K</mi><mi mathvariant="normal">L</mi></mrow><mrow><mo fence="true">(</mo><msub><mi>π</mi><mi>θ</mi></msub><mtext> </mtext><mi mathvariant="normal">∥</mi><mtext> </mtext><msub><mi>π</mi><mtext>ref</mtext></msub><mo fence="true">)</mo></mrow></mrow><annotation encoding="application/x-tex">\\max_\\theta\\ \\mathbb{E}_{x,\\ y \\sim \\pi_\\theta}\\left[r_\\phi(x,y)\\right] - \\beta \\cdot \\mathrm{KL}\\left(\\pi_\\theta \\,\\|\\, \\pi_{\\text{ref}}\\right) </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.5021em;vertical-align:-0.7521em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.4306em;"><span style="top:-2.3479em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">max</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7521em;"><span></span></span></span></span></span><span class="mspace">\xA0</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">x</span><span class="mpunct mtight">,</span><span class="mspace mtight"><span class="mtight">\xA0</span></span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span><span class="mrel mtight">∼</span><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3488em;margin-left:-0.0359em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1512em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">[</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">ϕ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mclose">)</span><span class="mclose delimcenter" style="top:0em;">]</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">KL</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">∥</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ref</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose delimcenter" style="top:0em;">)</span></span></span></span></span></span></p><p>KL 不是装饰。没有它，策略会跑到奖励模型的高分区域，而那个区域可能只是&quot;更长、更自信、格式更花哨&quot;——奖励模型被训练成拟合人的偏好，人的偏好里本来就有这些捷径。</p><p><strong>例（InstructGPT 的数据与结果）</strong></p><p>InstructGPT 用了约 40 名标注员：1.3 万条提示写示范，做 SFT；3.3 万条提示对 4 到 9 个输出排序，训练奖励模型；3.1 万条 API 提示只用奖励模型打分，做 PPO。论文报告的结果是：13 亿参数的 InstructGPT，输出比 1750 亿参数的 GPT-3 更受偏好。对齐的收益可以跨过两个数量级的参数差。</p><p>PPO 稳定，但它是为通用 RL 设计的，搬到 LLM 上要付三笔账。<strong>模型账</strong>：一次训练同时驻留策略、critic、奖励模型、参考模型四个模型，critic 与策略同规模，显存约为 SFT 的两倍。<strong>时间账</strong>：每步要做生成、打分、两次反向，训练时间是 SFT 的两到四倍。<strong>调参账</strong>：值函数学习率、GAE 的 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>γ</mi></mrow><annotation encoding="application/x-tex">\\gamma</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span></span></span></span> 与 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>λ</mi></mrow><annotation encoding="application/x-tex">\\lambda</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span></span></span></span>、裁剪系数、critic 更新频率，至少五个额外超参数。</p><p>它换来的好处是 token 级信用分配：critic 估计每个前缀的价值，策略能知道&quot;是哪一步开始走偏的&quot;。代价是这套信用分配本身很难学——整条回答只有一个最终奖励，critic 要从这个标量里拆出每个 token 的贡献。</p><p><strong>注意（评审偏差）</strong></p><p>奖励模型是从人的判断里学出来的，人的判断有偏，奖励就有偏。Chen 等人（EMNLP 2024）用 142 道题做了四组干预：插入事实错误、加入性别刻板印象、加一条假参考文献、加表情与 Markdown。每组的&quot;攻击成功率&quot;衡量判决被翻转的比例，越低越好。</p><p>结果并不整齐：识别错误信息时，人类 ASR 是 0.21，GPT-4o 是 0.06——强模型比人更能抓错；但在性别偏差上，人类是 0.06，GPT-4o 是 0.16，Claude-2 是 0.25；在权威偏差上，随机基线是 0.37，Claude-2 高达 0.89，一条假引用就能骗过评审。奖励模型继承这些偏差，RL 再把它们放大成策略行为。</p><h3 id="从-ppo-到-grpo-把-critic-换掉" tabindex="-1"><a class="header-anchor" href="#从-ppo-到-grpo-把-critic-换掉"><span>从 PPO 到 GRPO：把 critic 换掉</span></a></h3><p>LLM 的 RL 比通用 RL 简单：反馈快（一次推理几秒）、状态转移确定（追加一个 token）、一条轨迹只有一个奖励。既然如此，值不值得为它养一个 critic？</p><p>ReMax 的做法是回到 1992 年的 REINFORCE，只换一个基线：用贪心答案的奖励 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi><mo stretchy="false">(</mo><mi>x</mi><mo separator="true">,</mo><mover accent="true"><mi>y</mi><mo>^</mo></mover><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">r(x,\\hat{y})</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 作为 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>b</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">b(x)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">b</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span>。贪心答案不依赖采样，所以梯度无偏；每个 prompt 只多一次贪心解码，显存约为 PPO 的 54%，训练时间约为 62%。</p><p>GRPO 再往前一步：对同一个 prompt 采一组回答，用组内均值作基线，再除以组内标准差：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mover accent="true"><mi>A</mi><mo>^</mo></mover><mi>i</mi></msub><mo>=</mo><mfrac><mrow><msub><mi>r</mi><mi>i</mi></msub><mo>−</mo><mrow><mi mathvariant="normal">m</mi><mi mathvariant="normal">e</mi><mi mathvariant="normal">a</mi><mi mathvariant="normal">n</mi></mrow><mo stretchy="false">(</mo><msub><mi>r</mi><mn>1</mn></msub><mo separator="true">,</mo><mo>…</mo><mo separator="true">,</mo><msub><mi>r</mi><mi>G</mi></msub><mo stretchy="false">)</mo></mrow><mrow><mrow><mi mathvariant="normal">s</mi><mi mathvariant="normal">t</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false">(</mo><msub><mi>r</mi><mn>1</mn></msub><mo separator="true">,</mo><mo>…</mo><mo separator="true">,</mo><msub><mi>r</mi><mi>G</mi></msub><mo stretchy="false">)</mo></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\hat{A}_i = \\frac{r_i - \\mathrm{mean}(r_1,\\dots,r_G)}{\\mathrm{std}(r_1,\\dots,r_G)} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0968em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9468em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">A</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1111em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.363em;vertical-align:-0.936em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">std</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">G</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathrm">mean</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">G</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p><strong>例</strong></p><p>四个回答的奖励是 1、0、1、0，均值 0.5，标准差 0.5。四个 advantage 分别是 +1、−1、+1、−1：高于平均的被推高，低于平均的被压低。整个过程不需要 critic，也不需要奖励模型——只要有一个能判对错的验证器。</p><p>GRPO 也有失效的时候。一组样本全错，所有 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>r</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">r_i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 都是 0，advantage 全是 0，梯度消失；这组 prompt 就白采了。成功率 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>p</mi></mrow><annotation encoding="application/x-tex">p</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span> 的题目，大约要 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi mathvariant="normal">/</mi><mi>p</mi></mrow><annotation encoding="application/x-tex">1/p</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/</span><span class="mord mathnormal">p</span></span></span></span> 次采样才能看到第一个有用的梯度——<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>p</mi><mo>=</mo><mn>1</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">p=1\\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">1%</span></span></span></span> 时是 100 次，不是 8 次。后来的变体大多在修这类稳定性问题：Dr. GRPO 去掉长度与标准差的归一化，DAPO 用 clip-higher、跳过全对/全错组、改成 token 级损失，GSPO 把重要性比放到序列级以适配 MoE。它们的共同点是：都是 GRPO 在长回答、长训练、大模型上的补丁，不是新的范式。</p><h3 id="dpo-把奖励模型也消掉" tabindex="-1"><a class="header-anchor" href="#dpo-把奖励模型也消掉"><span>DPO：把奖励模型也消掉</span></a></h3><p>RLHF 的第三步是&quot;用奖励模型做 RL&quot;，DPO 问了一个更省事的问题：能不能不解 RL，直接用一个分类损失优化同一个目标？</p><p>可以。RLHF 的最优策略满足</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>r</mi><mo stretchy="false">(</mo><mi>x</mi><mo separator="true">,</mo><mi>y</mi><mo stretchy="false">)</mo><mo>=</mo><mi>β</mi><mi>log</mi><mo>⁡</mo><mfrac><mrow><msub><mi>π</mi><mi>θ</mi></msub><mo stretchy="false">(</mo><mi>y</mi><mo>∣</mo><mi>x</mi><mo stretchy="false">)</mo></mrow><mrow><msub><mi>π</mi><mtext>ref</mtext></msub><mo stretchy="false">(</mo><mi>y</mi><mo>∣</mo><mi>x</mi><mo stretchy="false">)</mo></mrow></mfrac><mo>+</mo><mtext>const</mtext></mrow><annotation encoding="application/x-tex">r(x,y) = \\beta \\log\\frac{\\pi_\\theta(y \\mid x)}{\\pi_{\\text{ref}}(y \\mid x)} + \\text{const} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.363em;vertical-align:-0.936em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ref</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord text"><span class="mord">const</span></span></span></span></span></span></p><p>把这个式子代回 Bradley–Terry，奖励模型就消掉了，只剩下策略与参考模型的对数概率差：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi mathvariant="script">L</mi><mtext>DPO</mtext></msub><mo>=</mo><mo>−</mo><mi>log</mi><mo>⁡</mo><mi>σ</mi><mrow><mo fence="true">(</mo><mi>β</mi><mi>log</mi><mo>⁡</mo><mfrac><mrow><msub><mi>π</mi><mi>θ</mi></msub><mo stretchy="false">(</mo><msub><mi>y</mi><mi>w</mi></msub><mo>∣</mo><mi>x</mi><mo stretchy="false">)</mo></mrow><mrow><msub><mi>π</mi><mtext>ref</mtext></msub><mo stretchy="false">(</mo><msub><mi>y</mi><mi>w</mi></msub><mo>∣</mo><mi>x</mi><mo stretchy="false">)</mo></mrow></mfrac><mo>−</mo><mi>β</mi><mi>log</mi><mo>⁡</mo><mfrac><mrow><msub><mi>π</mi><mi>θ</mi></msub><mo stretchy="false">(</mo><msub><mi>y</mi><mi>l</mi></msub><mo>∣</mo><mi>x</mi><mo stretchy="false">)</mo></mrow><mrow><msub><mi>π</mi><mtext>ref</mtext></msub><mo stretchy="false">(</mo><msub><mi>y</mi><mi>l</mi></msub><mo>∣</mo><mi>x</mi><mo stretchy="false">)</mo></mrow></mfrac><mo fence="true">)</mo></mrow></mrow><annotation encoding="application/x-tex">\\mathcal{L}_{\\text{DPO}} = -\\log \\sigma\\left(\\beta \\log\\frac{\\pi_\\theta(y_w \\mid x)}{\\pi_{\\text{ref}}(y_w \\mid x)} - \\beta \\log\\frac{\\pi_\\theta(y_l \\mid x)}{\\pi_{\\text{ref}}(y_l \\mid x)}\\right) </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">DPO</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.4em;vertical-align:-0.95em;"></span><span class="mord">−</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size3">(</span></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ref</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ref</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size3">)</span></span></span></span></span></span></span></p><p>直白地说：提高被选中回答的概率，降低被拒绝回答的概率，而且都相对于参考模型来算。它不需要奖励模型，不需要在线采样，训练成本约等于 SFT；Zephyr、Llama 3、Tülu 3 都用过。</p><p>DPO 的代价是<strong>离线</strong>。它学的是一个固定数据集里的偏好，数据往往由别的模型生成；模型在训练中不会探索&quot;自己会怎么写&quot;，也就不会发现自己没想到的更好回答。这就是 off-policy 的陷阱：训练分布与策略分布越走越远。修法是迭代 DPO、在线 DPO，或者回到 on-policy 的 RL。</p><h3 id="奖励从哪里来-rlhf-与-rlvr" tabindex="-1"><a class="header-anchor" href="#奖励从哪里来-rlhf-与-rlvr"><span>奖励从哪里来：RLHF 与 RLVR</span></a></h3><p>到这里，方法的分歧其实只有一个：<strong>奖励从哪里来</strong>。</p><table><thead><tr><th>任务</th><th>RLHF 的奖励</th><th>RLVR 的奖励</th></tr></thead><tbody><tr><td>创意写作</td><td>人比较两首诗</td><td>没有可判定的答案</td></tr><tr><td>安全</td><td>人判断哪个回答更稳妥</td><td>只能做粗粒度的规则检查</td></tr><tr><td>数学</td><td>人检查步骤</td><td>答案对错，1 或 0</td></tr><tr><td>代码</td><td>人读代码，慢且易错</td><td>单元测试通过率</td></tr><tr><td>Agent 任务</td><td>人看整条轨迹</td><td>最终状态是否正确</td></tr></tbody></table><p>RLVR（可验证奖励的强化学习）把奖励换成一个验证器：答案匹配、单元测试、规则格式。它的好处是精确、便宜、难被钻空子，可以跑几百万次 rollout；坏处是只适用于&quot;可判定&quot;的任务，奖励稀疏到只有 0 和 1。</p><p>这个转向解释了推理模型为什么在 2024 年之后集中出现。R1-Zero 直接在基座上跑 GRPO，奖励只有&quot;答案对不对&quot;和&quot;格式对不对&quot;，AIME 从 15.6% 升到 71.0%，没有用任何 SFT 数据；代价是可读性差、中英混杂。R1 在此基础上加了几千条冷启动数据、拒绝采样和全场景 RL，AIME 到 79.8%、MATH-500 到 97.3%。SimpleRL 把同一套配方缩到 7B：Qwen2.5-Math-7B-Base，8K 条 MATH，奖励 +1 / −0.5 / −1（答对、格式对但答错、格式错），平均提升 18.6 个点，AIME 比 SFT 高 30 个点，数据效率约为对比方法的 50 倍。</p><p>但 RLVR 不是终局。R1 的最后一个阶段仍然用奖励模型处理写作与通用对话；创意、安全、开放域问答没有可验证的答案，仍然要靠人的偏好或评分量表。更前沿的做法是把&quot;验证&quot;本身也学出来：DeepSeekMath-V2 用生成器、验证器、元验证器三层，验证器给证明打 0/0.5/1 并列出问题，元验证器再检查这些问题是否真实存在——奖励从&quot;人&quot;回到&quot;学出来的判断&quot;，但判断本身可被检查。</p><h3 id="从单步到多步-agentic-rl" tabindex="-1"><a class="header-anchor" href="#从单步到多步-agentic-rl"><span>从单步到多步：Agentic RL</span></a></h3><p>前面所有方法都共享一个隐含假设：一条轨迹只有一步。给一个 prompt，模型生成一条回答，奖励在结尾出现。RLHF 的偏好、RLVR 的对错、DPO 的 chosen/rejected，都是这个形状。</p><p>Agent 不是这个形状。它要读文件、调工具、看返回、改计划、再调工具；一条轨迹几十上百步，奖励只在任务完成时给一次；模型看到的也不是完整状态，而是工具输出、屏幕截图、文件系统的一部分。2025 年的一篇 Agentic RL 综述把这件事说得很清楚：LLM 的 RL 是退化的单步 MDP，Agentic RL 是时间上延展的、部分可观测的 POMDP。</p><p>这个区别不是术语游戏，它改变了四件事。</p><p><strong>第一，算力花在 rollout 上。</strong> 单步 RL 的一次 rollout 是一条回答；Agent 的一次 rollout 是几十轮工具调用、十万级 token 的上下文。生成这些轨迹比反向传播贵得多，训练时间被采样主导。Molt（2026）这样的框架把&quot;异步 rollout + 分布式经验存储&quot;当成核心设计，原因就在这里：同步训练要等最慢的那条轨迹，GPU 大部分时间在空转。</p><p><strong>第二，环境成了基础设施。</strong> 成千上万个隔离沙箱、代码执行、浏览器、检索、故障恢复、可复现——每一个都要在训练循环里稳定工作。工具会超时、会失败、会返回脏数据；异步采样让样本变旧，策略更新后旧样本的 importance ratio 要修正，修正不好就发散。</p><p><strong>第三，信用分配变难。</strong> 单步 RL 只需要判断&quot;这条回答好不好&quot;；Agent 要判断&quot;哪一步走错了&quot;。奖励稀疏、延迟、长尾，一个失败的轨迹可能是第 3 步选错工具，也可能是第 40 步没检查返回值。过程奖励模型、树搜索、值函数都在试图补这一层，但都还没有成为标准答案。</p><p><strong>第四，奖励更容易被钻空子。</strong> 数学题的验证器只检查最终答案；Agent 的验证器要检查环境状态。模型可以学会&quot;让测试通过&quot;而不是&quot;把功能做对&quot;，可以学会改测试、跳过失败、在日志里写成功。攻击面从答案扩展到了整个工具链。</p><p><strong>例（ARC-AGI-3 与 harness）</strong></p><p>ARC-AGI-3 是一个交互式推理基准：模型进入一个不知道规则的游戏环境，只能按键、观察、假设、再行动。它不按&quot;答对多少题&quot;打分，而按相对人类动作效率（RHAE）打分——不仅要通关，还要用不比人多的动作通关。</p><p>2026 年，NVIDIA 的 AVO 在公开集（25 个环境、183 个关卡）上拿到 100% RHAE，基座是 Claude Opus 5；ARC Prize 在另一套条件下评测同一个模型，RHAE 约为 30%。差别不在模型，在 harness：持久记忆、工具调用、状态管理、失败恢复，以及一个在卡住时把任务拉回正轨的监督器。这个例子不是&quot;RL 训练&quot;的证明，但它说明在长程任务里，模型只是系统的一部分，环境循环本身决定了上限。</p><p><strong>例（Molt：把 Agentic RL 做成基础设施）</strong></p><p>Molt（2026）是一个 PyTorch 原生的 Agentic RL 框架，代码量约 9.2K 行，支持万亿参数策略的训练；它把异步训练、分布式经验存储、OpenAI/Anthropic 兼容的 agent 接口放在一起。论文验证的是 1T 参数策略的完整 RL 流水线，以及 30B MoE agent 的持续学习。这类工作的意义不在于算法，而在于把&quot;采样—训练—环境&quot;这条链跑稳。</p><p>被问&quot;Agentic RL 和 RLHF 有什么区别&quot;时，答三点就够了：单步还是多步、奖励从哪来、信用分配落在哪一层。</p><p>对开发者来说，这一章最实用的三个结论：base 模型不能直接做产品，它只会续写；API 拿到的都是对齐后的模型，安全边界、拒绝率、回答风格都在这一层定型；对齐是行为与偏好，不是新知识，不要指望靠 SFT 或 RLHF 注入大规模事实。</p><p><strong>注意（奖励是代理）</strong></p><p>只要奖励是代理，策略就会去优化代理，而不是优化我们真正想要的东西。Goodhart 那句话在这里是字面意义的：当一个度量变成目标，它就不再是一个好的度量。</p><p>奖励黑客有几种常见形态：奖励模型分数继续上升、真实质量已经见顶（Gao 等人 2023 的过优化曲线）；更长、更自信、排版更漂亮的回答被系统性地偏好；模型学会迎合用户而不是保持正确（Sharma 等人 2023 的谄媚现象）。多步环境里还多一种：改测试、跳过失败、在日志里写成功。</p><p>工程上的防线有三条：用与奖励函数无关的独立测试集验收；把奖励拆成&quot;正确性 + 格式 + 风格&quot;多项，避免单一标量被刷；对长回答做长度与模板的控制。更根本的一条是：能验证的任务尽量用验证器，不能验证的任务才用偏好模型，并且承认偏好模型只是代理。</p><h2 id="六、推理模型-o1-r1-test-time-scaling-改变了什么" tabindex="-1"><a class="header-anchor" href="#六、推理模型-o1-r1-test-time-scaling-改变了什么"><span>六、推理模型（o1 / R1）：test-time scaling 改变了什么</span></a></h2><h3 id="背景-推理能力从-提示出来-到-训练出来" tabindex="-1"><a class="header-anchor" href="#背景-推理能力从-提示出来-到-训练出来"><span>背景：推理能力从&quot;提示出来&quot;到&quot;训练出来&quot;</span></a></h3><p>早期让大模型做复杂推理，靠的是在 prompt 里引导它&quot;逐步思考&quot;（CoT）。但 CoT 只是把模型<strong>已有的</strong>推理潜力显式化，复杂任务上仍然会中途走错、不自我纠错。OpenAI o1 和 DeepSeek R1 代表了一个范式的转变：<strong>把&quot;长思维链&quot;本身训练成模型的能力</strong>，并在推理时投入更多计算换取正确率。</p><p>机制上分训练与推理两侧：</p><ul><li><strong>训练侧</strong>：用强化学习（R1 走的就是&quot;可验证奖励 + GRPO&quot;路线）让模型在数学、代码这类能自动判分的任务上反复试错，学会自我纠错、回溯、换思路。判分是客观的（答案对不对、测试过不过），不依赖人类偏好打分。</li><li><strong>推理侧</strong>：模型在给出最终答案前先花大量 token 进行内部思考（reasoning），并把&quot;投入多少思考&quot;变成一个可调节量——这就是 <strong>test-time scaling</strong>：推理时算力越多，正确率越高，只不过收益递减。OpenAI 用 reasoning_effort 参数、Anthropic 的 extended thinking 用思考预算、DeepSeek R1 默认输出思考过程。</li></ul><h3 id="推理-token-与成本真相" tabindex="-1"><a class="header-anchor" href="#推理-token-与成本真相"><span>推理 token 与成本真相</span></a></h3><p>这类模型的成本结构和普通模型差异很大，接入前必须算清：</p><ul><li><strong>输出 token 大幅膨胀</strong>。一个数学题可能输出几千个思考 token 再加几百个答案 token，账单上的&quot;输出 token 数&quot;比普通模型多一个量级。虽然思考类输出单价通常低于答案单价（各家计价方式不同，以官方文档为准），总量仍然是主要成本来源。</li><li><strong>延迟显著上升</strong>。首 token 就要等思考完成一部分，P95 拉长是常态。实时交互、工具循环密集的 Agent 场景要评估是否划算。</li><li><strong>&quot;思考&quot;不是免费的推理增强</strong>。DeepSeek 的 API 会把 reasoning_content 一起返回，可以做评测与审计；OpenAI 默认隐藏思考细节，只给摘要，某些合规场景需要确认可接受。</li></ul><h3 id="该用和不该用的场景" tabindex="-1"><a class="header-anchor" href="#该用和不该用的场景"><span>该用和不该用的场景</span></a></h3><p><strong>推理模型真正受益的地方</strong>：数学证明与计算、复杂代码生成/调试（需要多步推演）、长链路规划、需要探索多个分支再收敛的问题、以及&quot;让模型扮演多步决策者&quot;的任务。</p><p><strong>不该无脑切过去的地方</strong>：简单事实问答、翻译、摘要、创意写作、对延迟敏感的交互、以及本来检索/规则就能解决的确定性任务。推理模型对简单问题同样会&quot;认真思考&quot;，经常更啰嗦、更慢、更贵，甚至出现<strong>过度思考</strong>——把简单问题复杂化。判断标准不是&quot;模型新不新&quot;，而是<strong>任务里是否真的存在需要推演的深度</strong>。</p><p>落地建议是做<strong>任务路由</strong>：默认走普通模型，检测到题目属于数学/逻辑/代码等复杂域（或简单模型评测不合格）再切推理模型，而不是把全站流量一次性切过去；切换前后在同一批评测样本上对比&quot;正确率提升 / 成本与延迟增加&quot;这笔账，用数据决定路由阈值。</p><h2 id="七、上下文窗口与-kv-cache-长上下文的成本与性能真相" tabindex="-1"><a class="header-anchor" href="#七、上下文窗口与-kv-cache-长上下文的成本与性能真相"><span>七、上下文窗口与 KV Cache：长上下文的成本与性能真相</span></a></h2><h3 id="kv-cache-是什么、为什么必须存在" tabindex="-1"><a class="header-anchor" href="#kv-cache-是什么、为什么必须存在"><span>KV Cache 是什么、为什么必须存在</span></a></h3><p>Decoder 是自回归逐 token 生成：生成第 L 个 token 时，每个注意力头都要拿当前 Q 去和<strong>全部历史位置的 K、V</strong> 计算。如果每步都把历史 token 重新过一遍网络重新算 K/V，代价随序列长度二次方膨胀，根本不可用。但历史的 K/V 只取决于历史本身，一旦算过就不会变——所以推理框架把它们按层缓存下来，每生成一个新 token 只需计算并追加它自己的 K/V，这就是 <strong>KV Cache</strong>。</p><p>KV Cache 是&quot;用显存换重复计算&quot;的经典工程决策，也是自回归推理的显存大头。它带来的直接推论是：<strong>推理时的显存占用随上下文长度线性增长</strong>，长上下文的贵不只在 API 账单上，也在自部署的显存规划上。</p><h3 id="规模直觉-kv-cache-到底吃多少显存" tabindex="-1"><a class="header-anchor" href="#规模直觉-kv-cache-到底吃多少显存"><span>规模直觉：KV Cache 到底吃多少显存</span></a></h3><p>单条序列的 KV 显存大致是：<code>2（K 和 V 两组）× 层数 × 单层 KV 维度 × 精度字节 × 序列长度</code>。用一个直观例子：32 层、隐层 4096、bf16 精度的模型，平均每个 token 的 KV 约占 2×32×4096×2B ≈ 512KB；8K 上下文就是 4GB 左右——这还没算模型权重和中间激活。<strong>并发用户数 × 平均上下文长度</strong>才是推理显存的真正公式，这也是&quot;为什么长上下文服务贵&quot;的物理根源。</p><p>业界缓解手段对应着不同的瓶颈：</p><ul><li><strong>GQA / MQA（分组查询注意力）</strong>：让多个 Q 头共享同一组 K/V 头，KV 显存直接除以分组比例。Llama 3、Qwen 等新一代模型普遍采用 GQA，这是&quot;新一代模型同样窗口下更省显存&quot;的原因之一。</li><li><strong>PagedAttention（vLLM 等推理框架）</strong>：KV 按块分页管理，消除预分配浪费、提高批处理利用率，让服务可以支撑更高的并发与更长的上下文。</li><li><strong>FlashAttention</strong>：通过分块与重计算把注意力中间矩阵不落显存，主要省的是<strong>中间激活的显存和访存</strong>，让更长序列能放进单卡；注意它不改变注意力的计算量（FLOPs 不变），长序列 prefill 依然慢。</li></ul><h3 id="长上下文的成本构成-prefill、decode-与-prompt-caching" tabindex="-1"><a class="header-anchor" href="#长上下文的成本构成-prefill、decode-与-prompt-caching"><span>长上下文的成本构成：prefill、decode 与 prompt caching</span></a></h3><p>一次请求的延迟和成本可以从两个阶段拆：</p><ul><li><strong>prefill（处理输入）</strong>：把整个 prompt 并行算一遍。全量注意力下计算量随输入长度近似二次方增长，FlashAttention 只优化访存不降 FLOPs，所以<strong>输入越长，首 token 时间（TTFT）越慢</strong>——这就是&quot;输入 token 贵&quot;的性能面。</li><li><strong>decode（逐 token 生成）</strong>：每步与已生成前缀线性相关，受显存带宽限制，所以<strong>输出 token 贵</strong>（时间长）。</li></ul><p>成本面则要理解各家 API 的 <strong>prompt caching</strong>：请求开头的一段 token 完全一致时，服务端可以直接复用前缀的 KV，输入成本从&quot;全价&quot;降为&quot;缓存读价&quot;（各家缓存保留窗口不同，以官方文档为准）。工程含义是：把系统提示、工具定义、长指令等<strong>不变内容放在最前面并保持顺序稳定</strong>，动态内容（用户消息、检索片段）只追加在后，命中率会显著提升；反过来，在稳定前缀中间插一句动态内容，整段前缀缓存全部失效，比不缓存更贵。工具定义这类内容注入得越多窗口占用越大，按需加载又容易打碎缓存，工具数量多起来以后，本质就是在&quot;全量注入占窗口&quot;与&quot;按需加载破坏缓存&quot;之间做权衡。</p><h3 id="长上下文不等于-更会用长上下文" tabindex="-1"><a class="header-anchor" href="#长上下文不等于-更会用长上下文"><span>长上下文不等于&quot;更会用长上下文&quot;</span></a></h3><p>上下文窗口宣传的是 128K、200K、1M，但真实使用有几个必须知道的边界：</p><ul><li><strong>Lost in the Middle</strong>：模型对放在长上下文中间位置的信息利用最差，文档越长、干扰越多，准确提取越难。窗口是&quot;放得下&quot;，不等于&quot;找得到&quot;。</li><li><strong>Needle-in-a-haystack 通过 ≠ 生产可用</strong>：单点事实抽取类基准容易过，但多文档对比、按时间/因果排序、跨文档推理这类真实长文档任务仍会明显退化。</li><li><strong>注意力有&quot;偏科&quot;</strong>：很多模型对序列开头和结尾的注意力系统性偏高（attention sink 现象），长上下文里中间段被稀释是普遍规律。</li></ul><p>所以工程上的一条铁律是：<strong>能用检索/切分解决的长文档需求，不要用&quot;整本塞进窗口&quot;解决</strong>。窗口大是降级方案（减少 RAG 管道复杂度的诱因），不是无脑方案；真实长文档场景上线前，请用自己文档上的&quot;多跳问题集&quot;而不是官方 demo 来验证。面试里被问&quot;KV Cache 是什么、为什么是瓶颈、GQA 和 FlashAttention 各解决什么&quot;，主线就是：解码复用 → 显存线性增长 → 分组共享压显存、分页提利用率、FlashAttention 减访存。</p><h2 id="八、幻觉-成因与工程化缓解" tabindex="-1"><a class="header-anchor" href="#八、幻觉-成因与工程化缓解"><span>八、幻觉：成因与工程化缓解</span></a></h2><h3 id="先定义清楚" tabindex="-1"><a class="header-anchor" href="#先定义清楚"><span>先定义清楚</span></a></h3><p>幻觉指模型生成了<strong>与事实或给定上下文不符</strong>的内容。工程上可以分两类：一类是<strong>事实性幻觉</strong>——编造了训练数据里不存在或记错的知识（人名、日期、数据、事件），来自参数记忆的不可靠；另一类是<strong>忠实性幻觉</strong>——明明给了检索文档/上下文，模型却脱离材料自由发挥，这是 RAG 场景下 90% 要处理的问题。两类成因不同，缓解手段也不同，先分清再动手。</p><h3 id="成因-模型为什么-会撒谎" tabindex="-1"><a class="header-anchor" href="#成因-模型为什么-会撒谎"><span>成因：模型为什么&quot;会撒谎&quot;</span></a></h3><p>把成因想清楚，才不会用错药：</p><ul><li>模型的训练目标是<strong>拟合词序列的分布</strong>，不是维护一个事实数据库。高频、多源印证的事实被&quot;记住&quot;得牢，长尾事实天然会被近似重建——这正是事实性幻觉的温床。</li><li>训练信号不奖励&quot;承认不知道&quot;。语料里&quot;我不知道&quot;&quot;这个信息可能不准确&quot;这类表述占比很低，模型没有足够的先验去主动拒绝；加上指令要求&quot;必须给出答案&quot;时，模型倾向于编一个听起来合理的答案。</li><li>知识有截止时间，但没有&quot;过期&quot;的自我认知。问训练截止之后的事件，模型仍会基于旧分布去续写。</li><li>上下文质量问题同样诱发幻觉：检索到的片段本身不相关或矛盾、上下文塞了过量的干扰信息、prompt 施加了&quot;只能回答不能拒绝&quot;的压力。</li></ul><p>有一个很容易被误解的点：<strong>降低 temperature 并不能消除幻觉</strong>。采样随机性只贡献了一小部分幻觉，把 temperature 调到 0 模型照样会一本正经地编造，因为它编的不是&quot;随机选错了&quot;，而是分布本身就给了错误答案较高概率。</p><h3 id="缓解-输入、生成、输出、评估四段治理" tabindex="-1"><a class="header-anchor" href="#缓解-输入、生成、输出、评估四段治理"><span>缓解：输入、生成、输出、评估四段治理</span></a></h3><ul><li><strong>输入侧</strong>：优先给模型&quot;可溯源的高置信内容&quot;而不是海量上下文——RAG 场景下检索质量与去噪比&quot;把什么都塞进去&quot;更重要；对关键事实附带来源；在 system 里明确&quot;不确定时如实说明，不要编造&quot;。</li><li><strong>生成侧</strong>：用约束降低自由发挥空间——要求只能基于给定材料作答、无依据的部分显式标注或拒绝；结构化输出（JSON Schema）减少发散；需要推理的任务给模型&quot;先核对上下文再下结论&quot;的空间。</li><li><strong>输出侧</strong>：做 <strong>grounding 校验</strong>——把答案里的关键断言拆出来，验证能否在给定上下文中找到证据，找不到就拒答或降级；代码类答案用真实执行验证，数值类答案交给计算器/工具，而不是让模型&quot;觉得对&quot;。</li><li><strong>评估侧</strong>：幻觉只能压到很低，做不到零。要构建以忠实度为核心的回归评测集，上线前后持续跑，bad case 回流改进检索与提示；业界 RAGAS 等框架里的 faithfulness 指标、以及 LLM-as-Judge 对&quot;答案是否忠于文档&quot;的打分，都是这套闭环的常用件。</li></ul><h3 id="误区与反例" tabindex="-1"><a class="header-anchor" href="#误区与反例"><span>误区与反例</span></a></h3><p><strong>&quot;用了 RAG 就没有幻觉&quot;是最大的误解</strong>。RAG 只是改善了上下文供给，检索结果错误、模型不忠于检索片段时幻觉照旧，所以上面第四层&quot;输出校验&quot;才是兜底。<strong>&quot;提示词里反复吓唬模型&quot;作用有限</strong>，它会提高拒答率但压不住高置信的错误输出；拒绝率升高本身也是产品问题——用户问的明明是正常问题却被反复&quot;无法确认&quot;，体验同样受损。另外注意<strong>引用也可能是幻觉</strong>：模型会编造格式正确但不存在的文献或 URL，给用户展示引用前必须先做真实性与可达性校验。</p><p>面试里&quot;模型幻觉怎么优化&quot;，按上面四段链路答就是完整主线；再强调一句&quot;无法根治、只能工程化压制&quot;的认知，比空谈&quot;用 RAG&quot;要加分。</p><h2 id="九、模型选型方法论-能力、成本、延迟、合规" tabindex="-1"><a class="header-anchor" href="#九、模型选型方法论-能力、成本、延迟、合规"><span>九、模型选型方法论：能力、成本、延迟、合规</span></a></h2><p>模型层最后一个决策问题是&quot;选哪个模型&quot;。最容易被带偏的做法是按排行榜或者朋友圈热度拍板——榜单测的是通用分布，你的业务是特定分布。选型的主线应该是：<strong>先建立能代表自己业务真实分布的评测集，再在候选模型上跑，最后按能力、成本、延迟、合规四个维度综合裁决</strong>。</p><h3 id="能力维度-拆成业务真正用到的能力" tabindex="-1"><a class="header-anchor" href="#能力维度-拆成业务真正用到的能力"><span>能力维度：拆成业务真正用到的能力</span></a></h3><p>&quot;模型强不强&quot;是伪命题，要拆成你业务里真实发生的行为：</p><ul><li><strong>语言与领域适配</strong>：中文产品必须重点测中文长文、中文术语、简体表达习惯，很多模型中英表现并不均衡。</li><li><strong>任务形态</strong>：你的核心任务是指令跟随、长文档抽取、多跳问答、代码生成，还是 Agent 式多轮工具调用？不同模型在不同形态上差异很大。</li><li><strong>结构化与工具调用可靠性</strong>：JSON 输出是否稳定合法、function calling 是否正确触发、参数是否规整——这些是 Agent 应用的命脉，但<strong>排行榜几乎不测</strong>，必须自己测。</li><li><strong>推理/多模态等加分项</strong>：是否真的需要，还是锦上添花。</li></ul><p>评测落地：自建三五十到几百条的 golden set（典型场景 + 边界场景 + 从生产 bad case 回流），用&quot;LLM-as-Judge 打分 + 人工抽检校准&quot;的方式批量对比。<strong>用数据而不是印象做决定</strong>，是选型工作的底线。</p><h3 id="成本维度-单价-×-真实用量形态" tabindex="-1"><a class="header-anchor" href="#成本维度-单价-×-真实用量形态"><span>成本维度：单价 × 真实用量形态</span></a></h3><p>成本不是&quot;每百万 token 多少钱&quot;这个表面对比，而是：</p><ul><li><strong>输入/输出比</strong>：输出单价通常高于输入。聊天、摘要类任务输出占比高，同样的&quot;百万 token 单价&quot;算出来完全不同。</li><li><strong>缓存命中</strong>：多轮、RAG 应用能命中 prompt caching 的比例，直接决定实际输入成本打几折。</li><li><strong>用量膨胀</strong>：多轮历史重发、检索片段注入会让平均输入远超&quot;单问题&quot;估值——把成本模型建立在真实流量形态上。</li><li><strong>自部署的隐藏成本</strong>：要按&quot;并发 × 上下文 × KV 显存&quot;算显存，还要算 GPU 折旧、电费、运维人力与版本升级负担。经常出现&quot;开源模型授权费为零、总成本反而更高&quot;的情况。</li></ul><h3 id="延迟维度-不止是快慢-还有稳定性" tabindex="-1"><a class="header-anchor" href="#延迟维度-不止是快慢-还有稳定性"><span>延迟维度：不止是快慢，还有稳定性</span></a></h3><p>API 场景看 P50 更要看 P95/P99：限流、高峰期排队、推理模型的思考时间都会让尾延迟暴涨。交互型产品（客服、Copilot）对 TTFT 敏感；Agent 场景还叠加多次串行调用，单次延迟被放大成端到端延迟。自部署则受 decode 带宽制约，长输出任务的实际吞吐要压测而不是看规格。</p><h3 id="合规维度-数据边界决定可选项" tabindex="-1"><a class="header-anchor" href="#合规维度-数据边界决定可选项"><span>合规维度：数据边界决定可选项</span></a></h3><p>把数据出境、数据用于训练、数据留存条款放在选型的第一道筛子里：涉密、政务、金融等场景可能直接排除境外 API；境内业务选择国产大模型（通义、智谱、DeepSeek、Kimi 等）通常数据留在境内且合规路径清晰。同时注意模型的<strong>内容安全与审计能力</strong>是否符合行业要求，以及开源模型的 license 是否允许你的商用方式。</p><h3 id="开源-vs-闭源-不是二选一-是场景分工" tabindex="-1"><a class="header-anchor" href="#开源-vs-闭源-不是二选一-是场景分工"><span>开源 vs 闭源：不是二选一，是场景分工</span></a></h3><table><thead><tr><th>维度</th><th>闭源 API</th><th>开源模型自部署</th></tr></thead><tbody><tr><td>数据边界</td><td>数据出境与训练条款受厂商约束</td><td>数据完全自控，可私有化</td></tr><tr><td>成本结构</td><td>按量付费，无硬件投入，小流量更划算</td><td>固定硬件投入，规模大摊薄成本</td></tr><tr><td>能力迭代</td><td>模型能力持续在线更新</td><td>依赖自己跟进版本、重新评测上线</td></tr><tr><td>运维负担</td><td>低，厂商兜底</td><td>高，需自己负责推理、监控、升级</td></tr></tbody></table><p>反例清单：<strong>只按榜单和跑分选型</strong>（不跑自己的任务）；<strong>只测单语言</strong>（中文业务只测英文榜单）；<strong>无脑上最大/最新模型</strong>（成本和延迟失控，简单任务大材小用）；<strong>只看输入单价</strong>（忽略输出、缓存与用量形态）；<strong>单点绑定一个厂商</strong>（没有逃生通道，厂商调价或下线就被动）。面试被问&quot;给公司做模型选型&quot;，把四维框架讲出来、再补一句&quot;先建自有评测集再谈选型&quot;，基本就是完整且正确的答案。</p><h2 id="十、主流上游模型-api-对比与网关设计" tabindex="-1"><a class="header-anchor" href="#十、主流上游模型-api-对比与网关设计"><span>十、主流上游模型 API 对比与网关设计</span></a></h2><h3 id="比较各家-api-看哪些维度" tabindex="-1"><a class="header-anchor" href="#比较各家-api-看哪些维度"><span>比较各家 API：看哪些维度</span></a></h3><p>模型 API 的价格表与能力榜更新极快，写死在笔记里很快就会过时，所以这里给&quot;对比时该看什么&quot;的清单，而不是结论：</p><ul><li><strong>接口兼容性</strong>：OpenAI 的 Chat Completions 格式事实上成了行业标准，DeepSeek、Kimi、通义等大多提供 OpenAI 兼容端点（改 base_url 即可试跑）；Anthropic 的 Messages 格式与 tool_use 结构自成一套，需要转换层或独立 adapter。</li><li><strong>工具调用与结构化输出</strong>：function calling 触发的稳定性、参数是否规整、JSON Schema 约束的强/弱（有的只是&quot;建议 JSON&quot;，有的是强制模式）、并行工具调用支持——这是 Agent 场景最该实测的一项。</li><li><strong>推理模型与 thinking tokens</strong>：是否支持 o1/R1 类推理模式、思考预算怎么控制、思考内容是否会返回（用于审计与评测）。</li><li><strong>上下文与真实长文档表现</strong>：官方窗口是一回事，多跳、多文档干扰下的实测是另一回事。</li><li><strong>计价口径</strong>：输入/输出单价、prompt caching 是显式还是自动、缓存读写价、reasoning token 是否单独计价、限流（RPM/TPM）——跨厂商比价必须对齐这些口径，否则就是拿苹果比橘子。</li><li><strong>可用性与合规</strong>：区域可用性、数据留存与训练条款、SLA。国产模型在境内合规与中文上是结构性优势。</li></ul><p>建议维护一张<strong>自更新的 provider 对比卡</strong>，把价格与限流这类高频变化信息放到配置与监控里，而不是硬编码进业务代码。</p><h3 id="为什么需要一层-接入-网关-抽象" tabindex="-1"><a class="header-anchor" href="#为什么需要一层-接入-网关-抽象"><span>为什么需要一层&quot;接入/网关&quot;抽象</span></a></h3><p>只要用过两个以上模型，就会体会到单点绑定一个厂商的风险：调价、下线、限流、能力回退，任何一项都可能打乱线上。网关层解决的是<strong>逃生通道、降级路由与统一治理</strong>：</p><ul><li><strong>统一入口与认证</strong>：密钥管理在服务端，客户端只面对一个内部端点。</li><li><strong>路由与降级</strong>：按任务类型路由（简单任务走小模型、复杂任务走大模型或推理模型）、按可用性做主备切换、按成本策略选路。</li><li><strong>重试与熔断</strong>：区分 429/5xx/超时做不同策略——429 做指数退避+抖动，5xx 短重试，连续失败触发熔断并切换到备用 provider。生成型 API 本身只读、重试安全，但如果网关后面编排了有副作用的工具执行，重试就需要幂等与去重。</li><li><strong>超时与流式</strong>：覆盖连接、首 token（TTFT）、总时长三档超时；流式输出做协议归一，避免换模型导致前端 SSE 事件结构变化。</li><li><strong>成本与观测</strong>：每次调用记录模型、输入/输出/reasoning token、缓存命中、延迟与费用，按业务线拆分预算；token 与成本异常暴涨要有告警。</li><li><strong>schema 校验兜底</strong>：不同模型对同一 prompt 的输出格式会漂移，网关对结构化输出统一做 JSON Schema 校验，失败自动单次重试或降级，而不是把脏数据发给下游。</li></ul><h3 id="兼容层的陷阱" tabindex="-1"><a class="header-anchor" href="#兼容层的陷阱"><span>兼容层的陷阱</span></a></h3><p>抽象层最大的坑是做成<strong>&quot;最弱公共子集&quot;</strong>：为了让所有 provider 都能过，把各家强项全部剥掉，结果换模型时能力体验反而全面下降。正解是能力探测 + 按能力路由——某家的超长窗口、某家的高稳定工具调用、某家的推理能力，允许&quot;只在该 provider 上启用&quot;的差异化路径，而不是强制抹平。</p><p>另外几个必须注意的工程点：prompt caching 策略各家不同（Anthropic 需要显式 cache_control 标记，OpenAI 系多为自动），切换 provider 后缓存收益要重新实测；不同模型的&quot;重试后结果&quot;可能有差异，重要场景要校验重试结果而不是盲信第一次或最后一次；跨 provider 的成本对比务必对齐计价口径，reasoning token、缓存 token 这类明细最容易漏算。</p>`,196)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};